#!/usr/bin/env bash
set -Eeuo pipefail

###############################################################################
# Portal Update 005
#
# Portal-owned identity, two-factor authentication, sign-in tracking,
# monitoring board, DNS services, notification channels and the
# Firewall theme.
#
# Brings a portal at update level 4 to level 5:
#
#   - Replaces the code tree with the current Portal source
#     (monitor page, monitor alerts, notification channels, DNS
#     services, network interface, appearance themes).
#   - Portal-owned authentication: credentials move into the
#     portal database (bcrypt). Existing users migrate
#     transparently on their next sign-in.
#   - Portal two-factor authentication (TOTP) with self-service
#     enrolment and admin reset.
#   - Sign-in tracking with client IP (Last Login / Source IP
#     on the Users page are portal-owned).
#   - Monitoring database bootstrap (connectivity heartbeat,
#     login feed, monitor alerts) + heartbeat systemd timer.
#   - Service accounts (api / portal-api) become Technitium
#     only and disappear from the portal.
#
# The api/config.php file and web uploads are preserved.
###############################################################################

UPDATE_NAME="Update 005 - Portal Identity, Two-Factor, Monitoring and DNS Services"

DB_NAME="dnsapproval"
API_DIR="/opt/portal/api"
WEB_DIR="/opt/portal/web"
PORTAL_DIR="/opt/portal"
CONFIG_FILE="$API_DIR/config.py"
VERSION_FILE="/var/lib/portal/update-version"
BACKUP_ROOT="/var/backups/portal"
STAGE_DIR=""
BACKUP_DIR=""
CODE_BACKUP_DONE=0
DB_BACKUP_DONE=0
MON_CREATED=0

log() { printf '\n======================================================================\n%s\n======================================================================\n' "$1"; }
ok() { echo "[ OK ] $1"; }
warn() { echo "[WARN] $1"; }
fail() { echo "[ERROR] $1" >&2; return 1; }

on_error() {
    local rc=$?
    trap - ERR EXIT
    if [[ $rc -ne 0 ]]; then
        echo ""
        warn "Update 005 failed (rc=$rc); starting rollback"
        rollback_update || warn "Rollback reported problems"
        fail "Update 005 aborted"
    fi
}

rollback_update() {

    if [[ "$CODE_BACKUP_DONE" -eq 1 && -f "$BACKUP_DIR/code-before.tar.gz" ]]; then
        tar -xzf "$BACKUP_DIR/code-before.tar.gz" -C / || warn "code restore failed"
        ok "Code tree restored"
    fi

    if [[ -f "$BACKUP_DIR/config.py.before" ]]; then
        cp -a "$BACKUP_DIR/config.py.before" "$CONFIG_FILE" || warn "config restore failed"
        ok "API config restored"
    fi

    if [[ "$DB_BACKUP_DONE" -eq 1 && -f "$BACKUP_DIR/dnsapproval-before.dump" ]]; then
        sudo -u postgres pg_restore --clean --if-exists \
            -d "$DB_NAME" "$BACKUP_DIR/dnsapproval-before.dump" \
            >/dev/null 2>&1 || warn "dnsapproval restore reported errors"
        ok "Portal database restored"
    fi

    if [[ "$MON_CREATED" -eq 1 && -f "$BACKUP_DIR/monitoring-before.dump" ]]; then
        sudo -u postgres pg_restore --clean --if-exists \
            -d monitoring_db "$BACKUP_DIR/monitoring-before.dump" \
            >/dev/null 2>&1 || warn "monitoring restore reported errors"
        ok "Monitoring database restored"
    fi

    systemctl restart portal-api.service >/dev/null 2>&1 || true
}

trap on_error EXIT

log "$UPDATE_NAME"

###############################################################################
# Preflight
###############################################################################

[[ $EUID -eq 0 ]] || fail "This update must be run as root"

for cmd in base64 curl find pg_dump pg_restore psql python3 systemctl tar; do
    command -v "$cmd" >/dev/null 2>&1 \
        || fail "Required command not found: $cmd"
done

[[ -f "$CONFIG_FILE" ]] || fail "File not found: $CONFIG_FILE"
[[ -d "$WEB_DIR" ]] || fail "Directory not found: $WEB_DIR"
[[ -f "$VERSION_FILE" ]] || fail "Update state file not found: $VERSION_FILE"

CURRENT_UPDATE="$(tr -d '[:space:]' < "$VERSION_FILE")"

if [[ ! "$CURRENT_UPDATE" =~ ^[0-9]+$ ]]; then
    fail "Invalid installed update level: $CURRENT_UPDATE"
fi

if (( CURRENT_UPDATE >= 5 )); then
    ok "Update 005 is already applied (level $CURRENT_UPDATE)"
    exit 0
fi

if (( CURRENT_UPDATE < 4 )); then
    fail "This update requires update level 4 (found $CURRENT_UPDATE). Apply the earlier updates first."
fi

ok "Installed update level: $CURRENT_UPDATE"

###############################################################################
# Stage + backups
###############################################################################

STAGE_DIR="$(mktemp -d /tmp/portal-update005.XXXXXX)"
BACKUP_DIR="$BACKUP_ROOT/update005-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$BACKUP_DIR"

PAYLOAD_B64="$STAGE_DIR/update005-payload.tar.gz.b64"
PERMISSIONS_B64="$STAGE_DIR/permissions.csv.b64"
SETTINGS_B64="$STAGE_DIR/portal-settings.csv.b64"
MON_SCHEMA_B64="$STAGE_DIR/monitoring-schema.sql.b64"
GRANTS_B64="$STAGE_DIR/group-grants.csv.b64"

log "BACKING UP CURRENT STATE"

# Only paths that exist on the target are backed up:
# notifier.py and scripts/ are NEW in this update and do
# not exist on a portal that is still at update level 4.

BACKUP_PATHS=""
for _path in \
    opt/portal/api/main.py \
    opt/portal/api/notifier.py \
    opt/portal/scripts \
    opt/portal/web
do
    [[ -e "/$_path" ]] && BACKUP_PATHS="$BACKUP_PATHS $_path"
done

[[ -n "$BACKUP_PATHS" ]] \
    || fail "nothing to back up"

tar -czf "$BACKUP_DIR/code-before.tar.gz" \
    -C / $BACKUP_PATHS 2>/dev/null \
    || fail "code backup failed"
CODE_BACKUP_DONE=1
ok "Code tree backed up"

cp -a "$CONFIG_FILE" "$BACKUP_DIR/config.py.before"
ok "API config backed up"

sudo -u postgres pg_dump -Fc -d "$DB_NAME" > "$BACKUP_DIR/dnsapproval-before.dump" \
    || fail "portal database backup failed"
DB_BACKUP_DONE=1
ok "Portal database backed up"

if sudo -u postgres psql -lqt -At -d postgres | cut -d'|' -f1 | grep -qx 'monitoring_db'; then
    sudo -u postgres pg_dump -Fc -d monitoring_db > "$BACKUP_DIR/monitoring-before.dump" \
        || fail "monitoring database backup failed"
    ok "Monitoring database backed up"
else
    MON_CREATED=1
    ok "Monitoring database does not exist yet (will be created)"
fi

###############################################################################
# Payload
###############################################################################

log "STAGING UPDATE PAYLOAD"

cat > "$PAYLOAD_B64" <<'UPDATE005_PAYLOAD_B64'
