###############################################################################
# Code installation
###############################################################################

log "INSTALLING PORTAL CODE"

tar -xzf "$STAGE_DIR/update005-payload.tar.gz" -C "$PORTAL_DIR/" \
    || fail "payload extraction failed"
ok "Code installed (config.php and uploads are preserved)"

###############################################################################
# API config: monitoring keys
###############################################################################

log "ENSURING API CONFIGURATION"

MON_PASSWORD="$(python3 -c 'import secrets; print(secrets.token_hex(24))')"

python3 - "$CONFIG_FILE" "$MON_PASSWORD" <<'PYEOF' || fail "config patch failed"
import sys

config_file, mon_password = sys.argv[1], sys.argv[2]

with open(config_file, "r", encoding="utf-8") as handle:
    content = handle.read()

if "MONITORING_POSTGRES_HOST" not in content:
    if content and not content.endswith("\n"):
        content += "\n"
    content += (
        "\n"
        "MONITORING_POSTGRES_HOST = \"127.0.0.1\"\n"
        "MONITORING_POSTGRES_DB = \"monitoring_db\"\n"
        "MONITORING_POSTGRES_USER = \"monitoring_user\"\n"
        "MONITORING_POSTGRES_PASSWORD = '%s'\n" % mon_password
    )
    with open(config_file, "w", encoding="utf-8") as handle:
        handle.write(content)
    print("[ OK ] Monitoring keys added to API config")
else:
    print("[ OK ] Monitoring keys already present")
PYEOF

###############################################################################
# Database: portal_auth + permissions + settings
###############################################################################

log "APPLYING PORTAL DATABASE MIGRATIONS"

sudo -u postgres psql -v ON_ERROR_STOP=1 -d "$DB_NAME" >/dev/null <<SQL || fail "portal database migration failed"
CREATE TABLE IF NOT EXISTS portal_auth (
    id SERIAL PRIMARY KEY,
    username VARCHAR(255) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    is_disabled BOOLEAN NOT NULL DEFAULT FALSE,
    must_change_password BOOLEAN NOT NULL DEFAULT FALSE,
    technitium_synced BOOLEAN NOT NULL DEFAULT TRUE,
    migrated_from_technitium BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP NOT NULL DEFAULT now(),
    updated_at TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT portal_auth_username_key UNIQUE (username)
);
CREATE UNIQUE INDEX IF NOT EXISTS portal_auth_username_lower_key
    ON portal_auth (LOWER(username));
ALTER TABLE portal_auth
    ADD COLUMN IF NOT EXISTS totp_secret VARCHAR(255),
    ADD COLUMN IF NOT EXISTS totp_pending_secret VARCHAR(255),
    ADD COLUMN IF NOT EXISTS totp_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS totp_last_timestep BIGINT;

ALTER TABLE requests
    ADD COLUMN IF NOT EXISTS requested_by VARCHAR(100),
    ADD COLUMN IF NOT EXISTS allow_minutes INTEGER,
    ADD COLUMN IF NOT EXISTS submitted_by VARCHAR(100);
SQL

ok "portal_auth ready (portal-owned credentials + two-factor)"

# The permission tree is REPLACED with the shipped tree: an
# update-004 portal still carries the old node names (Allow
# Lists / Block Lists / DNS Server ...) which the current
# pages no longer recognise. The rebuild maps every group
# back to its permissions by key, so nothing is lost.

python3 - "$STAGE_DIR/permissions.csv" "$STAGE_DIR/group-grants.csv" > "$STAGE_DIR/permissions-full.sql" <<'PYEOF' || fail "permission stage failed"
import sys

perm_rows = []
for line in open(sys.argv[1], encoding="utf-8"):
    line = line.strip()
    if not line:
        continue
    perm_id, parent, key, name = line.split("|", 3)
    perm_rows.append(
        "    (%s, %s, '%s', '%s')"
        % (
            int(perm_id),
            "NULL" if parent == "" else parent,
            key.replace("'", "''"),
            name.replace("'", "''"),
        )
    )

grant_rows = []
for line in open(sys.argv[2], encoding="utf-8"):
    line = line.strip()
    if not line or "|" not in line:
        continue
    group_name, key = line.split("|", 1)
    grant_rows.append(
        "    ('%s', '%s')"
        % (
            group_name.replace("'", "''"),
            key.replace("'", "''"),
        )
    )

print("BEGIN;")
print("CREATE TEMP TABLE perm_import (id INTEGER, parent INTEGER, key TEXT, name TEXT) ON COMMIT DROP;")
print("INSERT INTO perm_import VALUES")
print(",\n".join(perm_rows) + ";")
print("CREATE TEMP TABLE grant_import (group_name TEXT, key TEXT) ON COMMIT DROP;")
print("INSERT INTO grant_import VALUES")
print(",\n".join(grant_rows) + ";")
print("CREATE TEMP TABLE grants_snapshot AS")
print("SELECT gp.group_id, p.permission_key")
print("FROM group_permissions gp JOIN permissions p ON p.id = gp.permission_id;")
print("DELETE FROM permissions;")
print("INSERT INTO permissions (id, parent_id, permission_key, permission_name)")
print("SELECT id, NULL, key, name FROM perm_import WHERE parent IS NULL;")

for _ in range(4):
    print("INSERT INTO permissions (id, parent_id, permission_key, permission_name)")
    print("SELECT i.id, i.parent, i.key, i.name FROM perm_import i")
    print("WHERE i.parent IS NOT NULL")
    print("  AND EXISTS (SELECT 1 FROM permissions p WHERE p.id = i.parent)")
    print("  AND NOT EXISTS (SELECT 1 FROM permissions p WHERE p.id = i.id);")

print("INSERT INTO group_permissions (group_id, permission_id)")
print("SELECT g.id, p.id")
print("FROM grant_import gi")
print("JOIN groups g ON g.group_name = gi.group_name")
print("JOIN permissions p ON p.permission_key = gi.key")
print("ON CONFLICT DO NOTHING;")
print("INSERT INTO group_permissions (group_id, permission_id)")
print("SELECT gs.group_id, p.id")
print("FROM grants_snapshot gs")
print("JOIN permissions p ON p.permission_key = gs.permission_key")
print("ON CONFLICT DO NOTHING;")
print("SELECT setval(pg_get_serial_sequence('permissions','id'),")
print("COALESCE((SELECT MAX(id) FROM permissions), 1),")
print("EXISTS (SELECT 1 FROM permissions));")
print("COMMIT;")
PYEOF

sudo -u postgres psql -v ON_ERROR_STOP=1 -d "$DB_NAME" < "$STAGE_DIR/permissions-full.sql" >/dev/null \
    || fail "permission migration failed"

PERM_COUNT="$(sudo -u postgres psql -At -d "$DB_NAME" -c "SELECT count(*) FROM permissions")" \
    || fail "permission verification failed"

[[ "$PERM_COUNT" -ge 55 ]] \
    || fail "permission rebuild incomplete ($PERM_COUNT/55 nodes)"

ok "Permission tree reconciled ($PERM_COUNT nodes, group grants mapped by key)"

python3 - "$STAGE_DIR/portal-settings.csv" > "$STAGE_DIR/settings-seed.sql" <<'PYEOF' || fail "settings stage failed"
import sys

rows = []
for line in open(sys.argv[1], encoding="utf-8"):
    line = line.strip()
    if not line or "|" not in line:
        continue
    key, value = line.split("|", 1)
    rows.append("    ('%s', '%s')" % (
        key.replace("'", "''"),
        value.replace("'", "''").replace("\\", "\\\\")
    ))

print("INSERT INTO portal_settings (setting_key, setting_value) VALUES")
print(",\n".join(rows))
print("ON CONFLICT (setting_key) DO NOTHING;")
PYEOF

sudo -u postgres psql -v ON_ERROR_STOP=1 -d "$DB_NAME" < "$STAGE_DIR/settings-seed.sql" >/dev/null \
    || fail "portal settings seed failed"

ok "Portal settings seeded (missing keys only)"

###############################################################################
# Monitoring database bootstrap
###############################################################################

log "BOOTSTRAPPING MONITORING DATABASE"

if sudo -u postgres psql -lqt -At -d postgres | cut -d'|' -f1 | grep -qx 'monitoring_db'; then
    ok "Monitoring database already exists"
else
    sudo -u postgres psql -v ON_ERROR_STOP=1 -d postgres >/dev/null <<SQL || fail "monitoring role/database creation failed"
DO \$do\$ BEGIN
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'monitoring_user') THEN
        CREATE ROLE monitoring_user LOGIN PASSWORD '$MON_PASSWORD';
    ELSE
        ALTER ROLE monitoring_user LOGIN PASSWORD '$MON_PASSWORD';
    END IF;
END \$do\$;
SELECT 'CREATE DATABASE monitoring_db OWNER monitoring_user'
WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = 'monitoring_db')\gexec
SQL
    MON_CREATED=1
    ok "Monitoring role and database created"
fi

sed -e 's/^CREATE TABLE /CREATE TABLE IF NOT EXISTS /' \
    -e 's/^CREATE INDEX /CREATE INDEX IF NOT EXISTS /' \
    -e 's/^CREATE SCHEMA monitoring;/CREATE SCHEMA IF NOT EXISTS monitoring;/' \
    "$STAGE_DIR/monitoring-schema.sql" > "$STAGE_DIR/monitoring-schema-idempotent.sql"

sudo -u postgres psql -d monitoring_db < "$STAGE_DIR/monitoring-schema-idempotent.sql" >/dev/null 2>&1 || true

sudo -u postgres psql -v ON_ERROR_STOP=1 -d monitoring_db >/dev/null <<SQL || fail "monitoring finalisation failed"
ALTER TABLE monitoring.login_events
    ADD COLUMN IF NOT EXISTS source_ip TEXT;
GRANT ALL ON SCHEMA monitoring TO monitoring_user;
GRANT ALL ON ALL TABLES IN SCHEMA monitoring TO monitoring_user;
SQL

MON_TABLE_COUNT="$(sudo -u postgres psql -At -d monitoring_db -c "SELECT count(*) FROM information_schema.tables WHERE table_schema = 'monitoring'")" \
    || fail "monitoring database verification failed"

[[ "$MON_TABLE_COUNT" -ge 6 ]] \
    || fail "monitoring schema incomplete ($MON_TABLE_COUNT/6 tables)"

ok "Monitoring database ready (login feed + alerts + heartbeat metrics)"

###############################################################################
# Python dependencies
###############################################################################

log "INSTALLING PYTHON DEPENDENCIES"

"$API_DIR/venv/bin/pip" install --disable-pip-version-check -q \
    bcrypt pyotp qrcode pillow \
    || fail "python dependency installation failed"

"$API_DIR/venv/bin/python" -c 'import bcrypt, pyotp, qrcode' \
    || fail "python dependency verification failed"

ok "bcrypt, pyotp and qrcode installed"

###############################################################################
# Heartbeat timer
###############################################################################

log "INSTALLING CONNECTIVITY HEARTBEAT"

cat > /etc/systemd/system/portal-heartbeat.service <<'UPDATE005_HEARTBEAT_SERVICE'
[Unit]
Description=Portal connectivity heartbeat sender

[Service]
Type=oneshot
ExecStart=/usr/bin/python3 /opt/portal/scripts/heartbeat.py
UPDATE005_HEARTBEAT_SERVICE

cat > /etc/systemd/system/portal-heartbeat.timer <<'UPDATE005_HEARTBEAT_TIMER'
[Unit]
Description=Portal connectivity heartbeat (every minute)

[Timer]
OnBootSec=45s
OnUnitActiveSec=60s
AccuracySec=5s

[Install]
WantedBy=timers.target
UPDATE005_HEARTBEAT_TIMER

systemctl daemon-reload
systemctl enable --now portal-heartbeat.timer >/dev/null 2>&1 \
    || warn "portal-heartbeat.timer could not be enabled"

ok "Heartbeat timer installed"

###############################################################################
# Restart + verify
###############################################################################

log "RESTARTING PORTAL SERVICES"

systemctl restart portal-api.service || fail "portal-api restart failed"

READY=0
for _ in $(seq 1 30); do
    if curl -fsS --max-time 5 http://127.0.0.1:8000/portal-settings >/dev/null 2>&1; then
        READY=1
        break
    fi
    sleep 2
done

[[ "$READY" -eq 1 ]] || fail "Portal API did not become ready"

ok "Portal API is running"

if ! curl -fsS --max-time 5 -X POST http://127.0.0.1:8000/login \
        -H 'Content-Type: application/json' \
        -d '{"username":"__update005_probe__","password":"x"}' >/dev/null 2>&1; then
    warn "Login probe did not answer (check journalctl -u portal-api)"
else
    ok "Login endpoint responds"
fi

###############################################################################
# Finalise
###############################################################################

printf '%s\n' "5" > "$VERSION_FILE"
chmod 644 "$VERSION_FILE"

rm -rf "$STAGE_DIR"

log "UPDATE 005 COMPLETE"

echo ""
echo "Installed update level: 5"
echo "Backups:                $BACKUP_DIR"
echo ""
echo "Notes:"
echo "  - Existing users migrate to portal-owned credentials on"
echo "    their next sign-in (no password resets needed)."
echo "  - Two-factor enrolment is available per user under"
echo "    My Profile; admins can reset it from the Users page."
echo "  - Service accounts (api / portal-api) now live on"
echo "    Technitium only and no longer appear in the portal."
